-- CS336 Project 1: export Preliminary back to the source CSV shape.
-- Run after load.sql in psql:
--     \i export.sql
--
-- The assignment explicitly requests removal of sequence_number. The source file
-- contains that column but every value is blank, so this output has 77 columns.
-- FORCE_QUOTE reproduces the source file's all-fields-quoted data rows. Each typed
-- NULL is converted to empty text first so it is emitted as "" rather than an
-- unquoted empty field. ORDER BY restores the original input order.
--
-- Reference: https://www.postgresql.org/docs/current/sql-copy.html

\set ON_ERROR_STOP on
\timing on

-- psql backslash commands end at a newline, so the complete \copy command must
-- remain on the following single line.
\copy (SELECT COALESCE(as_of_year::text, '') AS as_of_year, COALESCE(respondent_id, '') AS respondent_id, COALESCE(agency_name, '') AS agency_name, COALESCE(agency_abbr, '') AS agency_abbr, COALESCE(agency_code::text, '') AS agency_code, COALESCE(loan_type_name, '') AS loan_type_name, COALESCE(loan_type::text, '') AS loan_type, COALESCE(property_type_name, '') AS property_type_name, COALESCE(property_type::text, '') AS property_type, COALESCE(loan_purpose_name, '') AS loan_purpose_name, COALESCE(loan_purpose::text, '') AS loan_purpose, COALESCE(owner_occupancy_name, '') AS owner_occupancy_name, COALESCE(owner_occupancy::text, '') AS owner_occupancy, COALESCE(loan_amount_000s::text, '') AS loan_amount_000s, COALESCE(preapproval_name, '') AS preapproval_name, COALESCE(preapproval::text, '') AS preapproval, COALESCE(action_taken_name, '') AS action_taken_name, COALESCE(action_taken::text, '') AS action_taken, COALESCE(msamd_name, '') AS msamd_name, COALESCE(msamd::text, '') AS msamd, COALESCE(state_name, '') AS state_name, COALESCE(state_abbr, '') AS state_abbr, COALESCE(state_code::text, '') AS state_code, COALESCE(county_name, '') AS county_name, COALESCE(county_code::text, '') AS county_code, COALESCE(census_tract_number, '') AS census_tract_number, COALESCE(applicant_ethnicity_name, '') AS applicant_ethnicity_name, COALESCE(applicant_ethnicity::text, '') AS applicant_ethnicity, COALESCE(co_applicant_ethnicity_name, '') AS co_applicant_ethnicity_name, COALESCE(co_applicant_ethnicity::text, '') AS co_applicant_ethnicity, COALESCE(applicant_race_name_1, '') AS applicant_race_name_1, COALESCE(applicant_race_1::text, '') AS applicant_race_1, COALESCE(applicant_race_name_2, '') AS applicant_race_name_2, COALESCE(applicant_race_2::text, '') AS applicant_race_2, COALESCE(applicant_race_name_3, '') AS applicant_race_name_3, COALESCE(applicant_race_3::text, '') AS applicant_race_3, COALESCE(applicant_race_name_4, '') AS applicant_race_name_4, COALESCE(applicant_race_4::text, '') AS applicant_race_4, COALESCE(applicant_race_name_5, '') AS applicant_race_name_5, COALESCE(applicant_race_5::text, '') AS applicant_race_5, COALESCE(co_applicant_race_name_1, '') AS co_applicant_race_name_1, COALESCE(co_applicant_race_1::text, '') AS co_applicant_race_1, COALESCE(co_applicant_race_name_2, '') AS co_applicant_race_name_2, COALESCE(co_applicant_race_2::text, '') AS co_applicant_race_2, COALESCE(co_applicant_race_name_3, '') AS co_applicant_race_name_3, COALESCE(co_applicant_race_3::text, '') AS co_applicant_race_3, COALESCE(co_applicant_race_name_4, '') AS co_applicant_race_name_4, COALESCE(co_applicant_race_4::text, '') AS co_applicant_race_4, COALESCE(co_applicant_race_name_5, '') AS co_applicant_race_name_5, COALESCE(co_applicant_race_5::text, '') AS co_applicant_race_5, COALESCE(applicant_sex_name, '') AS applicant_sex_name, COALESCE(applicant_sex::text, '') AS applicant_sex, COALESCE(co_applicant_sex_name, '') AS co_applicant_sex_name, COALESCE(co_applicant_sex::text, '') AS co_applicant_sex, COALESCE(applicant_income_000s::text, '') AS applicant_income_000s, COALESCE(purchaser_type_name, '') AS purchaser_type_name, COALESCE(purchaser_type::text, '') AS purchaser_type, COALESCE(denial_reason_name_1, '') AS denial_reason_name_1, COALESCE(denial_reason_1::text, '') AS denial_reason_1, COALESCE(denial_reason_name_2, '') AS denial_reason_name_2, COALESCE(denial_reason_2::text, '') AS denial_reason_2, COALESCE(denial_reason_name_3, '') AS denial_reason_name_3, COALESCE(denial_reason_3::text, '') AS denial_reason_3, COALESCE(to_char(rate_spread, 'FM00.00'), '') AS rate_spread, COALESCE(hoepa_status_name, '') AS hoepa_status_name, COALESCE(hoepa_status::text, '') AS hoepa_status, COALESCE(lien_status_name, '') AS lien_status_name, COALESCE(lien_status::text, '') AS lien_status, COALESCE(edit_status_name, '') AS edit_status_name, COALESCE(edit_status::text, '') AS edit_status, COALESCE(population::text, '') AS population, COALESCE(minority_population::text, '') AS minority_population, COALESCE(hud_median_family_income::text, '') AS hud_median_family_income, COALESCE(tract_to_msamd_income::text, '') AS tract_to_msamd_income, COALESCE(number_of_owner_occupied_units::text, '') AS number_of_owner_occupied_units, COALESCE(number_of_1_to_4_family_units::text, '') AS number_of_1_to_4_family_units, COALESCE(application_date_indicator::text, '') AS application_date_indicator FROM preliminary ORDER BY sequence_number) TO 'hmda_2017_nj_roundtrip_without_sequence.csv' WITH (FORMAT CSV, HEADER true, FORCE_QUOTE *);

\echo Exported hmda_2017_nj_roundtrip_without_sequence.csv
